//   Course Clips/ C - Castle/Castle Inside/ Section B/C-7 Back GFX / layer 'Layer 1' / frame 1 /   Course Items-PL/ In-course Items/ Transportation/ Doors/Main Door Clip
// onClipEvent(load)
void clip_2981_5_0(Activation& scope) {
    scope["doorplace"] = "C-8-1";
    scope["doortype"] = 4;
    //d10
    scope["locked"] = true;
    scope["keytype"] = 5;
    scope["unlockitem"] = "GreenStar";
    // Changed to locked till Kamek Battle
    if (_root["Star"][50] == true || _root["CheatCastleUnlock"] == true) {
        scope["removelock"] = true;
    }
    scope["dooropenarray"] = 9;
    //
    scope["doorlockfunction"] = scope.function([](Activation& scope) -> Value {
        _root["Course"]["Char"]["attack"] = true;
        _root["Course"]["Char"]["attackFrame"] = "Sign";
        _root["Course"]["Char"]["xspeed"] = 0;
        //
        _root["PlayMessage"]("This door won't open with just any number of Shine Sprites....  You'll need a <i>special</i> Shine Sprite to get through");
        _root["Mariosound"] = new_(Sound, scope.self);
        _root["Mariosound"]["attachSound"]("Bowser - Laugh Muffled");
        _root["Mariosound"]["start"](0, 1);
        _root["Mariosound"]["setVolume"](_root["MarioVolume"]);
        scope["count"] = 0;
        scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
            scope["X"] = scope["_x"] + scope["_parent"]["_x"];
            _root["Course"]["Char"]["_x"] += (scope["X"] - _root["Course"]["Char"]["_x"]) / 5;
            //
            _root["playpause"] = true;
            //
            scope["count"]++;
            if (_root["KeyZ"]() && scope["count"] > 5) {
                _root["StopMessage"]();
                //
                scope["count"] = 0;
                scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
                    scope["count"]++;
                    if (scope["count"] > 5) {
                        _root["playpause"] = false;
                        _root["Course"]["Char"]["attack"] = false;
                        scope["onEnterFrame"] = Value::null();
                        gotoAndStop(1);
                    }
                    return undefined;
                });
            }
            return undefined;
        });
        return undefined;
    });
}

