//   Course Clips/ C - Castle/Castle Inside/ Section B/C-7 Back GFX / layer 'Warps' / frame 2
void frame_2981_0(Activation& scope) {
    stop();
    _root["AreaTextClipF"]("Under the Castle:" + scope["newline"] + "<i>Basement</i>", 15);
    scope["playedsound"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        /*
        if (this.warp2.hitTest(_root.Course.Char.charClip.feet)) {
        _root.Course.Char.attack = true;
        _root.Course.Char.xspeed = 0;
        _root.Course.Char.yspeed = 0;
        _root.Course.Char.attackFrame = "none";
        warp = true;
        warpnum = 2;
        }
        */
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                if (scope["playedsound"] == false) {
                    _root["PaintingSound"]();
                }
                scope["playedsound"] = true;
                _root["attachMovie"]("uptransition", "uptransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            if (scope["warpnum"] == 2) {
                if (scope["playedsound"] == false) {
                    _root["PaintingSound"]();
                }
                scope["playedsound"] = true;
                _root["attachMovie"]("righttransition", "righttransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["Fluddpow"] = "";
                _root["StopBGsong"]();
                _root["Restartcoins"]();
                //_root.Playinglevel = ""
                _root["changecourse"]("uptransition2", "9-05", 0, 0, 0, 0, true);
            }
            if (scope["warpnum"] == 2) {
                _root["Fluddpow"] = "";
                _root["StopBGsong"]();
                _root["Restartcoins"]();
                //_root.Playinglevel = ""
                _root["changecourse"]("righttransition2", "9-03", 0, 0, 0, 0, true);
            }
        }
        return undefined;
    });
    if (_root["Star"][46] == true) {
        nextFrame();
    } else {
        stop();
    }
}

