//   Course Clips/ C - Castle/Castle Inside/ Section C & D/C-12 Back GFX / layer 'Layer 1' / frame 1 /   Course Items-PL/ In-course Items/ Transportation/ Doors/Star Door
// onClipEvent(load)
void clip_3195_1_0(Activation& scope) {
    scope["doorplace"] = "C-13-1";
    //
    scope["locked"] = true;
    scope["keytype"] = 1;
    if ((_root["TotalStars"] >= 32 && _root["CurrentPlayer"] == "Mario") || _root["CheatCastleUnlock"] == true) {
        scope["removelock"] = true;
    }
    //
    scope["doorlockfunction"] = scope.function([](Activation& scope) -> Value {
        _root["Course"]["Char"]["attack"] = true;
        _root["Course"]["Char"]["attackFrame"] = "Sign";
        _root["Course"]["Char"]["xspeed"] = 0;
        //
        if (strictNotEquals(_root["CurrentPlayer"], "Mario") && _root["TotalStars"] >= 32) {
            _root["PlayMessage"]("Your are not my Rival!  Go Away and bring Mario!");
        } else {
            _root["PlayMessage"]("You need a total of 32 Shine Sprites to unlock this door");
        }
        _root["Mariosound"] = new_(Sound, scope.self);
        _root["Mariosound"]["attachSound"]("Bowser - Laugh Muffled");
        _root["Mariosound"]["start"](0, 1);
        _root["Mariosound"]["setVolume"](_root["MarioVolume"]);
        scope["count"] = 0;
        scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
            scope["X"] = scope["_x"] + scope["_parent"]["_x"];
            _root["Course"]["Char"]["_x"] += (scope["X"] - _root["Course"]["Char"]["_x"]) / 5;
            //
            _root["playpause"] = true;
            //
            scope["count"]++;
            if (_root["KeyZ"]() && scope["count"] > 5) {
                _root["StopMessage"]();
                //
                scope["count"] = 0;
                scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
                    scope["count"]++;
                    if (scope["count"] > 5) {
                        _root["playpause"] = false;
                        _root["Course"]["Char"]["attack"] = false;
                        scope["onEnterFrame"] = Value::null();
                        //
                        _root["Course"]["Char"]["attack"] = true;
                        _root["Course"]["Char"]["xspeed"] = 0;
                        _root["Course"]["Char"]["attackFrame"] = "Door";
                        _root["door"] = scope["doorplace"];
                        gotoAndPlay("play");
                        //
                    }
                    return undefined;
                });
            }
            return undefined;
        });
        return undefined;
    });
}

